[CmdletBinding()]
param(
    [switch]$InstallBuildTools,
    [switch]$SkipSystemPackages
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$Root = Split-Path -Parent $PSScriptRoot
$LockPath = Join-Path $Root "requirements\WINDOWS_PREREQUISITES.lock.json"
$ToolsRoot = Join-Path $Root ".tools"
$Bin = Join-Path $ToolsRoot "bin"

function Invoke-Native([scriptblock]$Command, [string]$Description) {
    & $Command
    if ($LASTEXITCODE -ne 0) {
        throw "$Description failed with exit code $LASTEXITCODE"
    }
}

function Assert-ArchiveHash([string]$Path, [string]$Expected) {
    if (-not (Test-Path $Path)) { throw "Missing cached toolchain archive: $Path" }
    $actual = (Get-FileHash -Algorithm SHA256 $Path).Hash.ToLowerInvariant()
    if ($actual -ne $Expected.ToLowerInvariant()) {
        throw "Hash mismatch for $Path"
    }
}

function Expand-TarGz([string]$Archive, [string]$Destination) {
    Remove-Item -Recurse -Force $Destination -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force $Destination | Out-Null
    tar -xzf $Archive -C $Destination
    if ($LASTEXITCODE -ne 0) { throw "Failed to extract $Archive" }
}

function Ensure-WingetPackage([string]$Name, [string]$Id, [string]$Probe, [string]$Override = "") {
    if (Get-Command $Probe -ErrorAction SilentlyContinue) {
        Write-Host "$Name already available"
        return
    }
    if ($SkipSystemPackages) { throw "$Name is missing and -SkipSystemPackages was used." }
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        throw "winget is required to install missing system package $Name."
    }
    $args = @("install", "--id", $Id, "--exact", "--accept-source-agreements", "--accept-package-agreements")
    if ($Override) { $args += @("--override", $Override) }
    & winget @args
    if ($LASTEXITCODE -ne 0) { throw "Failed to install $Name" }
}

$lock = Get-Content -Raw $LockPath | ConvertFrom-Json
if ([Environment]::Is64BitOperatingSystem -ne $true) { throw "Windows x64 is required." }

if (-not $SkipSystemPackages) {
    Ensure-WingetPackage "Git for Windows" "Git.Git" "git"
    Ensure-WingetPackage "Python 3.10+" "Python.Python.3.10" "python"
    if ($InstallBuildTools) {
        $build = $lock.system_packages | Where-Object { $_.winget_id -eq "Microsoft.VisualStudio.2022.BuildTools" }
        if (-not $build) { throw "Build Tools lock entry is missing." }
        if (-not (Get-Command vswhere.exe -ErrorAction SilentlyContinue)) {
            Ensure-WingetPackage "Visual Studio Build Tools 2022" $build.winget_id "vswhere.exe" $build.override
        }
    }
}

New-Item -ItemType Directory -Force $ToolsRoot, $Bin | Out-Null

$node = $lock.cached_toolchain_packages | Where-Object { $_.package -eq "node-win-x64@24.13.1" }
$pnpm = $lock.cached_toolchain_packages | Where-Object { $_.package -eq "pnpm@11.10.0" }
$corepack = $lock.cached_toolchain_packages | Where-Object { $_.package -eq "corepack@0.35.0" }
if (-not $node -or -not $pnpm -or -not $corepack) { throw "Pinned cached toolchain entries are incomplete." }

$nodeArchive = Join-Path $Root $node.archive
$pnpmArchive = Join-Path $Root $pnpm.archive
$corepackArchive = Join-Path $Root $corepack.archive
Assert-ArchiveHash $nodeArchive $node.sha256
Assert-ArchiveHash $pnpmArchive $pnpm.sha256
Assert-ArchiveHash $corepackArchive $corepack.sha256

$nodeRoot = Join-Path $ToolsRoot "node-24.13.1"
$pnpmRoot = Join-Path $ToolsRoot "pnpm-11.10.0"
$corepackRoot = Join-Path $ToolsRoot "corepack-0.35.0"
Expand-TarGz $nodeArchive $nodeRoot
Expand-TarGz $pnpmArchive $pnpmRoot
Expand-TarGz $corepackArchive $corepackRoot

$nodeExe = Join-Path $nodeRoot ($node.executable -replace '/', '\')
$pnpmCjs = Join-Path $pnpmRoot ($pnpm.entrypoint -replace '/', '\')
$corepackJs = Join-Path $corepackRoot ($corepack.entrypoint -replace '/', '\')
foreach ($required in @($nodeExe, $pnpmCjs, $corepackJs)) {
    if (-not (Test-Path $required)) { throw "Pinned toolchain entry is missing after extraction: $required" }
}

$nodeVersion = (& $nodeExe --version).Trim()
if ($nodeVersion -ne $node.expected_version) { throw "Cached Node version mismatch: $nodeVersion" }
$pnpmVersion = (& $nodeExe $pnpmCjs --version).Trim()
if ($pnpmVersion -ne "11.10.0") { throw "Cached pnpm version mismatch: $pnpmVersion" }

$nodeShim = "@echo off`r`n`"$nodeExe`" %*`r`n"
$pnpmShim = "@echo off`r`n`"$nodeExe`" `"$pnpmCjs`" %*`r`n"
$corepackShim = "@echo off`r`n`"$nodeExe`" `"$corepackJs`" %*`r`n"
Set-Content -Encoding Ascii (Join-Path $Bin "node.cmd") $nodeShim
Set-Content -Encoding Ascii (Join-Path $Bin "pnpm.cmd") $pnpmShim
Set-Content -Encoding Ascii (Join-Path $Bin "pnpx.cmd") $pnpmShim
Set-Content -Encoding Ascii (Join-Path $Bin "corepack.cmd") $corepackShim

$env:PATH = "$Bin;$env:PATH"
Invoke-Native { node --version } "Node verification"
Invoke-Native { pnpm --version } "pnpm verification"
Invoke-Native { corepack --version } "Corepack verification"
Write-Host "Pinned local toolchain installed under $ToolsRoot"

[CmdletBinding()]
param(
    [switch]$SkipInstall,
    [switch]$SkipBuild,
    [switch]$SkipTests
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$Root = Split-Path -Parent $PSScriptRoot
$Source = Join-Path $Root "source\primary"
$Lock = Join-Path $Root "source\SOURCE_LOCK.json"
$Artifacts = Join-Path $Root "artifacts\baseline"

function Invoke-Logged([string]$Name, [scriptblock]$Command) {
    $log = Join-Path $Artifacts ($Name + ".log")
    Write-Host "Running $Name"
    & $Command *>&1 | Tee-Object -FilePath $log
    $code = $LASTEXITCODE
    if ($null -eq $code) { $code = 0 }
    Set-Content -Encoding Ascii (Join-Path $Artifacts ($Name + ".exit-code")) $code
    if ($code -ne 0) { throw "$Name failed with exit code $code" }
}

if (-not (Test-Path $Lock)) { throw "source/SOURCE_LOCK.json is required." }
if (-not (Test-Path (Join-Path $Source ".git"))) { throw "Git source is required for baseline capture." }
New-Item -ItemType Directory -Force $Artifacts | Out-Null

$sourceLock = Get-Content -Raw $Lock | ConvertFrom-Json
$expected = $sourceLock.expected_commit
$actual = (& git -C $Source rev-parse HEAD).Trim().ToLowerInvariant()
if ($actual -ne $expected.ToLowerInvariant()) { throw "Source commit does not match source lock." }
if ((& git -C $Source status --porcelain) -join "`n") { throw "Source must be clean before baseline." }

$node = (& node --version).Trim()
$pnpm = (& pnpm --version).Trim()
if ($node -ne "v24.13.1") { throw "Node v24.13.1 required, got $node" }
if ($pnpm -ne "11.10.0") { throw "pnpm 11.10.0 required, got $pnpm" }

$pre = [ordered]@{
    captured_at_utc = [DateTime]::UtcNow.ToString("o")
    commit = $actual
    tree = (& git -C $Source rev-parse 'HEAD^{tree}').Trim()
    node = $node
    pnpm = $pnpm
    git = (& git --version).Trim()
    operating_system = [System.Environment]::OSVersion.VersionString
    architecture = [System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture.ToString()
    clean_before = $true
}
$pre | ConvertTo-Json -Depth 4 | Set-Content -Encoding UTF8 (Join-Path $Artifacts "environment.json")
& git -C $Source submodule status --recursive *>&1 | Set-Content -Encoding UTF8 (Join-Path $Artifacts "submodules.txt")

Push-Location $Source
try {
    if (-not $SkipInstall) { Invoke-Logged "01-install" { pnpm install --frozen-lockfile } }
    Invoke-Logged "02-typecheck" { pnpm run typecheck }
    Invoke-Logged "03-lint" { pnpm run lint }
    if (-not $SkipTests) { Invoke-Logged "04-tests" { pnpm test } }
    if (-not $SkipBuild) { Invoke-Logged "05-build" { pnpm run build } }
} finally {
    Pop-Location
}

$status = (& git -C $Source status --porcelain) -join "`n"
$status | Set-Content -Encoding UTF8 (Join-Path $Artifacts "post-baseline-status.txt")
if ($status) { throw "Baseline commands dirtied the source tree." }

$result = [ordered]@{
    status = "passed"
    commit = $actual
    clean_after = $true
    finished_at_utc = [DateTime]::UtcNow.ToString("o")
}
$result | ConvertTo-Json | Set-Content -Encoding UTF8 (Join-Path $Artifacts "BASELINE_RESULT.json")
Write-Host "Baseline captured without modifying source."

#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SOURCE="$ROOT/source/primary"
LOCK="$ROOT/source/SOURCE_LOCK.json"
ART="$ROOT/artifacts/baseline"
mkdir -p "$ART"
[[ -f "$LOCK" && -d "$SOURCE/.git" ]] || { echo "Source lock and Git checkout required" >&2; exit 1; }
EXPECTED="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["expected_commit"])' "$LOCK")"
[[ "$(git -C "$SOURCE" rev-parse HEAD)" == "$EXPECTED" ]] || { echo "Source commit mismatch" >&2; exit 1; }
[[ -z "$(git -C "$SOURCE" status --porcelain)" ]] || { echo "Source dirty before baseline" >&2; exit 1; }
cd "$SOURCE"
run() { local name="$1"; shift; "$@" 2>&1 | tee "$ART/$name.log"; echo "${PIPESTATUS[0]}" > "$ART/$name.exit-code"; [[ "${PIPESTATUS[0]}" == 0 ]]; }
run 01-install pnpm install --frozen-lockfile
run 02-typecheck pnpm run typecheck
run 03-lint pnpm run lint
run 04-tests pnpm test
run 05-build pnpm run build
[[ -z "$(git status --porcelain)" ]] || { echo "Source dirty after baseline" >&2; exit 1; }
printf '{"status":"passed","commit":"%s"}\n' "$EXPECTED" > "$ART/BASELINE_RESULT.json"
